async function pxLookup(form){const input=form.elements.identity,q=input.value.trim();const sequence=px.lookupSequence=(px.lookupSequence||0)+1;form.elements.user_id.value='';px.lookup={query:q,status:'loading'};const box=form.querySelector('[data-px-customer-results]');if(!q){box.innerHTML='';px.lookup={query:q,status:'empty'};return px.lookup}box.innerHTML='<small role="status">Ищем клиента…</small>';try{const x=await pxFetch('/api/web/admin/users/search','POST',{q,page:1,limit:10,status:'all'});if(!Array.isArray(x.items))throw Error('Не удалось прочитать список клиентов');if(sequence!==px.lookupSequence||!form.isConnected||input.value.trim()!==q)return null;px.lookup={query:q,status:'ready',items:x.items};box.innerHTML=x.items.length?x.items.map(u=>`<button type="button" class="fo-button fo-button--row" data-px-choose-user="${u.id}"><span>${esc(u.name)}</span><small>${esc(u.freeman_id||'')}</small></button>`).join(''):'<small role="status">Клиент не найден. Будет создано приглашение для регистрации на сайте или входа через бота.</small>';return px.lookup}catch(err){if(sequence===px.lookupSequence&&form.isConnected){px.lookup={query:q,status:'error'};box.innerHTML=`<small class="px-error">${esc(err.message)}. Повторите поиск.</small>`}return null}}
